import type { ButtonSize, ButtonVariant } from "./button.types";

// Class strings stay literal so Uniwind can discover them.

export const variants: Record<
  ButtonVariant,
  { container: string; label: string }
> = {
  primary: { container: "bg-primary border-primary", label: "text-on-primary" },
  secondary: {
    container: "bg-surface border-border",
    label: "text-foreground",
  },
  ghost: {
    container: "bg-transparent border-transparent",
    label: "text-muted",
  },
  outline: {
    container: "bg-transparent border-border",
    label: "text-foreground",
  },
};

/**
 * Visible heights match beUI web (32, 40, 48). `hitSlop` tops the touch area up
 * to 48 points; content may grow taller for larger text.
 */
export const sizes: Record<
  ButtonSize,
  {
    container: string;
    radius: string;
    label: string;
    icon: number;
    gap: number;
    hitSlop: number;
  }
> = {
  sm: {
    container: "min-h-8 px-3 py-1 gap-1.5",
    radius: "rounded-full",
    label: "text-xs",
    icon: 14,
    gap: 6,
    hitSlop: 8,
  },
  md: {
    container: "min-h-10 px-5 py-2 gap-2",
    radius: "rounded-full",
    label: "text-sm",
    icon: 16,
    gap: 8,
    hitSlop: 4,
  },
  lg: {
    container: "min-h-12 px-6 py-2 gap-2",
    radius: "rounded-full",
    label: "text-base",
    icon: 18,
    gap: 8,
    hitSlop: 0,
  },
  icon: {
    container: "h-8 w-8",
    radius: "rounded-lg",
    label: "text-sm",
    icon: 16,
    gap: 0,
    hitSlop: 8,
  },
};

import { createContext, useContext, useEffect, useRef, useState } from "react";
import {
  type ColorValue,
  Pressable,
  StyleSheet,
  Text,
  type TextProps,
  View,
} from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { useResolveClassNames } from "uniwind";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { renderIcon } from "../../primitives/render-icon";
import { EASE_OUT, motion } from "../../styles/motion";
import { sizes, variants } from "./button.styles";
import type {
  ButtonIcon as ButtonIconType,
  ButtonProps,
  ButtonRootProps,
  ButtonSize,
  ButtonVariant,
} from "./button.types";

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

const HOVER_SCALE = 1.02;
const RIPPLE_DURATION = 1600;

type ButtonContextValue = {
  variant: ButtonVariant;
  size: ButtonSize;
  color: ColorValue | undefined;
};

const ButtonContext = createContext<ButtonContextValue | null>(null);

/** Internal: size, variant and resolved foreground color of the enclosing button. */
export function useButtonContext() {
  const context = useContext(ButtonContext);
  if (!context) throw new Error("Button content must be rendered in a Button.");
  return context;
}

export { renderIcon as renderButtonIcon };

function ButtonLabel({ className = "", ...props }: TextProps) {
  const { variant, size } = useButtonContext();
  return (
    <Text
      {...props}
      className={`shrink text-center font-medium ${sizes[size].label} ${variants[variant].label} ${className}`}
    />
  );
}

function ButtonIcon({ icon }: { icon: ButtonIconType }) {
  const { size, color } = useButtonContext();
  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      aria-hidden
      style={styles.icon}
    >
      {renderIcon(icon, { size: sizes[size].icon, color })}
    </View>
  );
}

type Ripple = { id: number; x: number; y: number; size: number };

function RippleDot({ ripple, color }: { ripple: Ripple; color: ColorValue }) {
  const progress = useSharedValue(0);

  useEffect(() => {
    progress.value = withTiming(1, {
      duration: RIPPLE_DURATION,
      easing: EASE_OUT,
    });
  }, [progress]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: 0.3 * (1 - progress.value),
    transform: [{ scale: 0.05 + 0.95 * progress.value }],
  }));

  return (
    <Animated.View
      style={[
        styles.ripple,
        {
          left: ripple.x - ripple.size / 2,
          top: ripple.y - ripple.size / 2,
          width: ripple.size,
          height: ripple.size,
          borderRadius: ripple.size / 2,
          backgroundColor: color,
        },
        animatedStyle,
      ]}
    />
  );
}

/** Internal: the pressable surface, rendering arbitrary content. */
export function ButtonRoot({
  variant = "primary",
  size = "md",
  pressScale = 0.93,
  ripple = false,
  disableAnimation = false,
  disabled: disabledProp,
  children,
  className = "",
  style,
  hitSlop,
  accessibilityState,
  onPressIn,
  onPressOut,
  onHoverIn,
  onHoverOut,
  ref,
  ...props
}: ButtonRootProps) {
  const disabled = disabledProp ?? false;
  const reducedMotion = useReducedMotionPreference();
  const animate = !reducedMotion && !disableAnimation;
  const appearance = variants[variant];
  const dimensions = sizes[size];
  const { color } = useResolveClassNames(appearance.label);

  const scale = useSharedValue(1);
  const pressed = useSharedValue(false);
  const hovered = useSharedValue(false);
  const layout = useRef({ width: 0, height: 0 });
  const nextRippleId = useRef(0);
  const rippleTimers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const [ripples, setRipples] = useState<Ripple[]>([]);

  useEffect(() => {
    const timers = rippleTimers.current;
    return () => {
      for (const timer of timers) clearTimeout(timer);
    };
  }, []);

  useEffect(() => {
    if (!animate || disabled) scale.value = 1;
  }, [animate, disabled, scale]);

  const animatedStyle = useAnimatedStyle(
    () => ({
      transform: [{ scale: scale.value }],
      // Without scale, pressing still needs visible feedback.
      opacity: disabled ? 0.5 : !animate && pressed.value ? 0.7 : 1,
    }),
    [animate, disabled],
  );

  const restScale = () => (hovered.value ? HOVER_SCALE : 1);

  return (
    <ButtonContext.Provider value={{ variant, size, color }}>
      <AnimatedPressable
        {...props}
        ref={ref}
        accessible
        accessibilityRole="button"
        accessibilityState={{ ...accessibilityState, disabled }}
        aria-disabled={disabled}
        disabled={disabled}
        hitSlop={hitSlop ?? dimensions.hitSlop}
        // Hugs its content unless the caller places it with a self-* class; on web,
        // a default self-start would otherwise win over the caller's.
        className={`${/\bself-/.test(className) ? "" : "self-start"} flex-row items-center justify-center border ${appearance.container} ${dimensions.container} ${dimensions.radius} ${className}`}
        style={[style, animatedStyle]}
        onPressIn={(event) => {
          pressed.value = true;
          if (animate) scale.value = withSpring(pressScale, motion.press);
          if (ripple && animate && color) {
            const { locationX, locationY } = event.nativeEvent;
            const { width, height } = layout.current;
            const id = nextRippleId.current++;
            setRipples((current) => [
              ...current,
              {
                id,
                x: locationX,
                y: locationY,
                size: Math.max(width, height) * 2,
              },
            ]);
            const timer = setTimeout(() => {
              rippleTimers.current.delete(timer);
              setRipples((current) => current.filter((r) => r.id !== id));
            }, RIPPLE_DURATION);
            rippleTimers.current.add(timer);
          }
          onPressIn?.(event);
        }}
        onPressOut={(event) => {
          pressed.value = false;
          if (animate) scale.value = withSpring(restScale(), motion.press);
          onPressOut?.(event);
        }}
        onHoverIn={(event) => {
          hovered.value = true;
          if (animate && !pressed.value) {
            scale.value = withSpring(HOVER_SCALE, motion.press);
          }
          onHoverIn?.(event);
        }}
        onHoverOut={(event) => {
          hovered.value = false;
          if (animate && !pressed.value) {
            scale.value = withSpring(1, motion.press);
          }
          onHoverOut?.(event);
        }}
      >
        {ripple && (
          <View
            className={`absolute inset-0 overflow-hidden ${dimensions.radius}`}
            style={styles.passThrough}
            onLayout={({ nativeEvent }) => {
              layout.current = nativeEvent.layout;
            }}
          >
            {color != null &&
              ripples.map((item) => (
                <RippleDot key={item.id} ripple={item} color={color} />
              ))}
          </View>
        )}
        {children}
      </AnimatedPressable>
    </ButtonContext.Provider>
  );
}

export function Button(props: ButtonProps) {
  if (props.size === "icon") {
    const { icon, ...rest } = props;
    return (
      <ButtonRoot {...rest}>
        <ButtonIcon icon={icon} />
      </ButtonRoot>
    );
  }
  const { startIcon, endIcon, children, ...rest } = props;
  const label = Array.isArray(children) ? children.join("") : String(children);
  return (
    <ButtonRoot {...rest}>
      {startIcon != null && <ButtonIcon icon={startIcon} />}
      <ButtonLabel>{label}</ButtonLabel>
      {endIcon != null && <ButtonIcon icon={endIcon} />}
    </ButtonRoot>
  );
}

const styles = StyleSheet.create({
  icon: { flexShrink: 0 },
  passThrough: { pointerEvents: "none" },
  ripple: { position: "absolute" },
});

import type { ReactNode, Ref } from "react";
import type { PressableProps, StyleProp, View, ViewStyle } from "react-native";
import type { IconProps, IconSource } from "../../primitives/render-icon";

export type ButtonVariant = "primary" | "secondary" | "ghost" | "outline";
export type ButtonSize = "sm" | "md" | "lg" | "icon";
export type ButtonIconProps = IconProps;
/** A component receiving `{ size, color }` (such as a lucide icon), or a prebuilt node. */
export type ButtonIcon = IconSource;

export type ButtonBaseProps = Omit<PressableProps, "children" | "style"> & {
  variant?: ButtonVariant;
  /** Scale while pressed. Defaults to 0.93, matching beUI web. */
  pressScale?: number;
  /** Spawn a ripple from the press point. Off by default. */
  ripple?: boolean;
  /** Disables press motion independently of the system preference. */
  disableAnimation?: boolean;
  style?: StyleProp<ViewStyle>;
  ref?: Ref<View>;
};

/** Internal props for the shared pressable surface. */
export type ButtonRootProps = ButtonBaseProps & {
  size?: ButtonSize;
  children?: ReactNode;
};

/** Accepts interpolated JSX text such as `Save {count} items`. */
export type ButtonText = string | number | readonly (string | number)[];

export type ButtonProps = ButtonBaseProps &
  (
    | {
        size?: Exclude<ButtonSize, "icon">;
        children: ButtonText;
        startIcon?: ButtonIcon;
        endIcon?: ButtonIcon;
        icon?: never;
      }
    | {
        size: "icon";
        icon: ButtonIcon;
        /** Icon buttons have no visible text, so they need a spoken name. */
        accessibilityLabel: string;
        children?: never;
        startIcon?: never;
        endIcon?: never;
      }
  );

export type ButtonState = "idle" | "loading" | "success" | "error";

export type StatefulButtonProps = ButtonBaseProps & {
  size?: Exclude<ButtonSize, "icon">;
  state?: ButtonState;
  /** The idle label. Latin labels cascade letter by letter; other scripts slide as a whole. */
  children: string;
  loadingText?: string;
  successText?: string;
  errorText?: string;
  /** Trailing icon shown only while idle. */
  icon?: ButtonIcon;
  loadingIcon?: ButtonIcon;
  successIcon?: ButtonIcon;
  errorIcon?: ButtonIcon;
};

export { Button } from "./button";
export type {
  ButtonBaseProps,
  ButtonIcon,
  ButtonIconProps,
  ButtonProps,
  ButtonSize,
  ButtonState,
  ButtonText,
  ButtonVariant,
  StatefulButtonProps,
} from "./button.types";
export { StatefulButton } from "./stateful-button";
export { CheckIcon, CrossIcon, Spinner } from "./status-icons";

import { useEffect, useRef } from "react";
import { AccessibilityInfo, StyleSheet, View } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { usePresence } from "../../hooks/use-presence";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { CascadeText } from "../../primitives/cascade-text";
import { motion } from "../../styles/motion";
import { ButtonRoot, renderButtonIcon, useButtonContext } from "./button";
import { sizes, variants } from "./button.styles";
import type {
  ButtonIcon,
  ButtonState,
  StatefulButtonProps,
} from "./button.types";
import { CheckIcon, CrossIcon, Spinner } from "./status-icons";

function IconSlot({
  icon,
  appear,
  exiting,
  side,
  reduce,
}: {
  icon: ButtonIcon;
  appear: boolean;
  exiting: boolean;
  side: "start" | "end";
  reduce: boolean;
}) {
  const { size, color } = useButtonContext();
  const { icon: iconSize, gap } = sizes[size];
  const slot = iconSize + gap;
  const progress = useSharedValue(appear ? 0 : 1);

  useEffect(() => {
    progress.value = reduce
      ? withTiming(exiting ? 0 : 1, motion.fade)
      : exiting
        ? withTiming(0, motion.exit)
        : withSpring(1, motion.swap);
  }, [exiting, progress, reduce]);

  const slotStyle = useAnimatedStyle(
    () => ({
      // Width collapses with the icon so the row never pops in a single frame.
      width: reduce ? (exiting ? 0 : slot) : Math.max(0, slot * progress.value),
    }),
    [exiting, reduce, slot],
  );
  const iconStyle = useAnimatedStyle(
    () => ({
      opacity: Math.min(1, Math.max(0, progress.value)),
      transform: [{ scale: reduce ? 1 : 0.7 + 0.3 * progress.value }],
    }),
    [reduce],
  );

  return (
    <Animated.View
      style={[
        styles.iconSlot,
        side === "start" ? styles.alignStart : styles.alignEnd,
        slotStyle,
      ]}
    >
      <Animated.View style={iconStyle}>
        {renderButtonIcon(icon, { size: iconSize, color })}
      </Animated.View>
    </Animated.View>
  );
}

function StatefulContent({
  state,
  text,
  icon,
  statusIcons,
}: {
  state: ButtonState;
  text: string;
  icon: ButtonIcon | undefined;
  statusIcons: Record<Exclude<ButtonState, "idle">, ButtonIcon>;
}) {
  const reduce = useReducedMotionPreference();
  const { size, variant } = useButtonContext();
  const leading = usePresence(
    state === "idle" ? null : state,
    state,
    () => motion.exit.duration + 40,
  );
  const trailing = usePresence(
    state === "idle" && icon != null ? "idle" : null,
    icon,
    () => motion.exit.duration + 40,
  );

  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={styles.content}
    >
      {leading.map((item) =>
        item.value === "idle" ? null : (
          <IconSlot
            key={item.key}
            icon={statusIcons[item.value]}
            appear={item.appear}
            exiting={item.exiting}
            side="start"
            reduce={reduce}
          />
        ),
      )}
      <CascadeText
        textKey={`${state}-${text}`}
        text={text}
        className={`font-medium ${sizes[size].label} ${variants[variant].label}`}
        reduce={reduce}
      />
      {trailing.map((item) => (
        <IconSlot
          key={item.key}
          icon={item.value}
          appear={item.appear}
          exiting={item.exiting}
          side="end"
          reduce={reduce}
        />
      ))}
    </View>
  );
}

export function StatefulButton({
  state = "idle",
  children,
  loadingText = "Loading",
  successText = "Done",
  errorText = "Try again",
  icon,
  loadingIcon = Spinner,
  successIcon = CheckIcon,
  errorIcon = CrossIcon,
  disabled,
  accessibilityLabel,
  accessibilityState,
  ...props
}: StatefulButtonProps) {
  const busy = state === "loading";
  const text =
    state === "loading"
      ? loadingText
      : state === "success"
        ? successText
        : state === "error"
          ? errorText
          : children;
  const previousState = useRef(state);

  // The button keeps focus while its name changes, so announce status changes explicitly.
  useEffect(() => {
    if (previousState.current === state) return;
    previousState.current = state;
    if (state !== "idle") AccessibilityInfo.announceForAccessibility(text);
  }, [state, text]);

  return (
    <ButtonRoot
      {...props}
      disabled={disabled || busy}
      accessibilityLabel={accessibilityLabel ?? text}
      accessibilityState={{ ...accessibilityState, busy }}
      aria-busy={busy}
    >
      <StatefulContent
        state={state}
        text={text}
        icon={icon}
        statusIcons={{
          loading: loadingIcon,
          success: successIcon,
          error: errorIcon,
        }}
      />
    </ButtonRoot>
  );
}

const styles = StyleSheet.create({
  content: { flexDirection: "row", alignItems: "center", flexShrink: 1 },
  iconSlot: {
    flexDirection: "row",
    alignItems: "center",
    overflow: "hidden",
    flexShrink: 0,
  },
  alignStart: { justifyContent: "flex-start" },
  alignEnd: { justifyContent: "flex-end" },
});

import { useEffect } from "react";
import { StyleSheet, View } from "react-native";
import Animated, {
  cancelAnimation,
  Easing,
  ReduceMotion,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withTiming,
} from "react-native-reanimated";
import type { ButtonIconProps } from "./button.types";

// Dependency-free status glyphs drawn with borders, so the button works with any icon set.

function strokeFor(size: number) {
  return Math.max(1.5, size / 9);
}

/** A three-quarter ring that keeps turning; progress is essential, so it ignores reduced motion. */
export function Spinner({ size, color }: ButtonIconProps) {
  const rotation = useSharedValue(0);

  useEffect(() => {
    rotation.value = withRepeat(
      withTiming(360, {
        duration: 800,
        easing: Easing.linear,
        reduceMotion: ReduceMotion.Never,
      }),
      -1,
      false,
    );
    return () => cancelAnimation(rotation);
  }, [rotation]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ rotate: `${rotation.value}deg` }],
  }));

  const ring = size * 0.8;
  return (
    <View style={[styles.box, { width: size, height: size }]}>
      <Animated.View
        style={[
          {
            width: ring,
            height: ring,
            borderRadius: ring / 2,
            borderWidth: strokeFor(size),
            borderColor: color,
            borderTopColor: "transparent",
          },
          animatedStyle,
        ]}
      />
    </View>
  );
}

export function CheckIcon({ size, color }: ButtonIconProps) {
  const stroke = strokeFor(size);
  return (
    <View style={[styles.box, { width: size, height: size }]}>
      <View
        style={{
          width: size * 0.3,
          height: size * 0.6,
          marginTop: -size * 0.12,
          borderRightWidth: stroke,
          borderBottomWidth: stroke,
          borderColor: color,
          borderBottomRightRadius: stroke / 2,
          transform: [{ rotate: "45deg" }],
        }}
      />
    </View>
  );
}

export function CrossIcon({ size, color }: ButtonIconProps) {
  const stroke = strokeFor(size);
  const bar = {
    position: "absolute" as const,
    width: size * 0.7,
    height: stroke,
    borderRadius: stroke / 2,
    backgroundColor: color,
  };
  return (
    <View style={[styles.box, { width: size, height: size }]}>
      <View style={[bar, { transform: [{ rotate: "45deg" }] }]} />
      <View style={[bar, { transform: [{ rotate: "-45deg" }] }]} />
    </View>
  );
}

const styles = StyleSheet.create({
  box: { alignItems: "center", justifyContent: "center" },
});

