// Color math, matching the web version.

/** Hue 0-360, saturation and value 0-100, alpha 0-1. */
export type Hsva = { h: number; s: number; v: number; a: number };
/** Channels 0-255, alpha 0-1. */
export type Rgba = { r: number; g: number; b: number; a: number };

export const clamp = (n: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, n));

const round = (n: number, places = 0) => {
  const f = 10 ** places;
  return Math.round(n * f) / f;
};

export function hsvaToRgba({ h, s, v, a }: Hsva): Rgba {
  const sat = s / 100;
  const val = v / 100;
  const f = (n: number) => {
    const k = (n + h / 60) % 6;
    return val - val * sat * Math.max(0, Math.min(k, 4 - k, 1));
  };
  return {
    r: Math.round(f(5) * 255),
    g: Math.round(f(3) * 255),
    b: Math.round(f(1) * 255),
    a,
  };
}

/** `previous` keeps hue for greys and saturation for black, which RGB can't carry. */
export function rgbaToHsva({ r, g, b, a }: Rgba, previous?: Hsva): Hsva {
  const rn = r / 255;
  const gn = g / 255;
  const bn = b / 255;
  const max = Math.max(rn, gn, bn);
  const d = max - Math.min(rn, gn, bn);
  let h = previous?.h ?? 0;
  if (d) {
    if (max === rn) h = ((gn - bn) / d) % 6;
    else if (max === gn) h = (bn - rn) / d + 2;
    else h = (rn - gn) / d + 4;
    h = (h * 60 + 360) % 360;
  }
  const v = max * 100;
  const s = max ? (d / max) * 100 : (previous?.s ?? 0);
  return { h, s, v, a };
}

const HEX_PATTERN = /^#?([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;

/** Parses #rgb, #rgba, #rrggbb and #rrggbbaa. Returns null for anything else. */
export function parseHex(input: string): Rgba | null {
  const match = HEX_PATTERN.exec(input.trim());
  const digits = match?.[1];
  if (!digits) return null;
  const hex =
    digits.length <= 4 ? [...digits].map((c) => c + c).join("") : digits;
  const n = (i: number) => Number.parseInt(hex.slice(i, i + 2), 16);
  return {
    r: n(0),
    g: n(2),
    b: n(4),
    a: hex.length === 8 ? round(n(6) / 255, 2) : 1,
  };
}

/** Lowercase #rrggbb, or #rrggbbaa when the color is translucent. */
export function formatHex({ r, g, b, a }: Rgba): string {
  const pair = (n: number) => Math.round(n).toString(16).padStart(2, "0");
  return `#${pair(r)}${pair(g)}${pair(b)}${a < 1 ? pair(a * 255) : ""}`;
}

export function hsvToHsl({ h, s, v }: Hsva) {
  const sv = s / 100;
  const vv = v / 100;
  const l = vv * (1 - sv / 2);
  const sl = l === 0 || l === 1 ? 0 : (vv - l) / Math.min(l, 1 - l);
  return { h, s: sl * 100, l: l * 100 };
}

export function hslToHsv(
  h: number,
  s: number,
  l: number,
  previous: Hsva,
  a: number,
): Hsva {
  const sl = s / 100;
  const ll = l / 100;
  const v = ll + sl * Math.min(ll, 1 - ll);
  return { h, s: v ? 2 * (1 - ll / v) * 100 : previous.s, v: v * 100, a };
}

export const BLACK: Rgba = { r: 0, g: 0, b: 0, a: 1 };

/** `rgba(…)` for a color, with an optional alpha override. */
export function rgbaString({ r, g, b, a }: Rgba, alpha = a) {
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

/** The fully saturated, fully bright color for a hue. */
export function hueColor(h: number) {
  return rgbaString(hsvaToRgba({ h, s: 100, v: 100, a: 1 }));
}

import {
  createContext,
  type ReactNode,
  type RefObject,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
} from "react";
import { View, type ViewProps } from "react-native";
import { type SharedValue, useSharedValue } from "react-native-reanimated";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import {
  BLACK,
  clamp,
  formatHex,
  type Hsva,
  hsvaToRgba,
  parseHex,
  type Rgba,
  rgbaToHsva,
} from "./color";

/** A frame in window coordinates. */
export type Frame = { x: number; y: number; width: number; height: number };

export type ColorPickerContextValue = {
  hsva: Hsva;
  rgba: Rgba;
  hex: string;
  alpha: boolean;
  disabled: boolean;
  reduce: boolean;
  /** Sets the color live, clamping each channel. */
  update: (next: Hsva) => void;
  /** Reports the settled color through onValueCommit. */
  commit: () => void;
  open: boolean;
  setOpen: (open: boolean) => void;
  /** 0 closed to 1 open; drives the panel and its rows. */
  progress: SharedValue<number>;
  /** The trigger, which the panel lines up under. */
  triggerRef: RefObject<View | null>;
  triggerFrame: Frame | null;
};

const ColorPickerContext = createContext<ColorPickerContextValue | null>(null);

export function usePickerContext(component: string) {
  const context = useContext(ColorPickerContext);
  if (!context) {
    throw new Error(`${component} must be used within <ColorPicker>`);
  }
  return context;
}

/** The picker's state, for custom parts. */
export function useColorPicker() {
  const { hsva, rgba, hex, update, commit, open, setOpen } =
    usePickerContext("useColorPicker");
  return { hsva, rgba, hex, update, commit, open, setOpen };
}

export type ColorPickerProps = Omit<ViewProps, "children"> & {
  /** Controlled hex color. Omit it and use `defaultValue` for uncontrolled use. */
  value?: string;
  /** Defaults to "#3478f6". */
  defaultValue?: string;
  /** Called on every change, such as each step of a drag. */
  onValueChange?: (value: string) => void;
  /** Called when a change settles: a drag ends, a field is submitted, a preset is picked. */
  onValueCommit?: (value: string) => void;
  /** Allows translucent colors and shows the opacity slider. Defaults to true. */
  alpha?: boolean;
  disabled?: boolean;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Moves without springing, independently of the system preference. */
  disableAnimation?: boolean;
  className?: string;
  children: ReactNode;
};

/**
 * A color picker built from parts: ColorPickerTrigger opens ColorPickerContent,
 * which holds the area, sliders, fields and presets. The parts also work
 * inline, without a trigger.
 */
export function ColorPicker({
  value,
  defaultValue = "#3478f6",
  onValueChange,
  onValueCommit,
  alpha = true,
  disabled = false,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  disableAnimation = false,
  className = "",
  children,
  ...props
}: ColorPickerProps) {
  const reducedMotion = useReducedMotionPreference();
  const reduce = reducedMotion || disableAnimation;
  const triggerRef = useRef<View>(null);
  const [triggerFrame, setTriggerFrame] = useState<Frame | null>(null);
  const progress = useSharedValue(defaultOpen ? 1 : 0);

  const [openInternal, setOpenInternal] = useState(defaultOpen);
  const open = openProp ?? openInternal;
  const setOpen = useCallback(
    (next: boolean) => {
      if (next === open || (next && disabled)) return;
      const apply = () => {
        if (openProp === undefined) setOpenInternal(next);
        onOpenChange?.(next);
      };
      if (!next) {
        apply();
        return;
      }
      // Find the trigger on screen before the panel appears beside it.
      if (!triggerRef.current) {
        apply();
        return;
      }
      triggerRef.current.measureInWindow((x, y, width, height) => {
        setTriggerFrame({ x, y, width, height });
        apply();
      });
    },
    [disabled, onOpenChange, open, openProp],
  );

  const controlled = value !== undefined;
  const incoming = controlled ? value : defaultValue;
  const [state, setState] = useState(() => ({
    source: incoming,
    hsva: rgbaToHsva(parseHex(incoming) ?? BLACK),
  }));

  // A controlled value the picker didn't emit is read during render, so the
  // thumbs never show a stale color for a frame.
  let hsva = state.hsva;
  if (controlled && value !== state.source) {
    const parsed = parseHex(value);
    hsva = parsed ? rgbaToHsva(parsed, state.hsva) : state.hsva;
    setState({ source: value, hsva });
  }
  if (!alpha && hsva.a !== 1) hsva = { ...hsva, a: 1 };

  const rgba = hsvaToRgba(hsva);
  const hex = formatHex(rgba);
  // Handlers read the latest emitted hex, which can be ahead of the render.
  const hexRef = useRef(hex);
  hexRef.current = hex;

  const update = useCallback(
    (next: Hsva) => {
      const clean: Hsva = {
        h: clamp(next.h, 0, 360),
        s: clamp(next.s, 0, 100),
        v: clamp(next.v, 0, 100),
        a: alpha ? clamp(next.a, 0, 1) : 1,
      };
      const nextHex = formatHex(hsvaToRgba(clean));
      const changed = nextHex !== hexRef.current;
      hexRef.current = nextHex;
      setState({ source: nextHex, hsva: clean });
      if (changed) onValueChange?.(nextHex);
    },
    [alpha, onValueChange],
  );
  const commit = useCallback(
    () => onValueCommit?.(hexRef.current),
    [onValueCommit],
  );

  const context = useMemo<ColorPickerContextValue>(
    () => ({
      hsva,
      rgba,
      hex,
      alpha,
      disabled,
      reduce,
      update,
      commit,
      open,
      setOpen,
      progress,
      triggerRef,
      triggerFrame,
    }),
    [
      alpha,
      commit,
      disabled,
      hex,
      hsva,
      open,
      progress,
      reduce,
      rgba,
      setOpen,
      triggerFrame,
      update,
    ],
  );

  return (
    <ColorPickerContext.Provider value={context}>
      <View
        {...props}
        className={`${disabled ? "opacity-50" : ""} ${className}`}
      >
        {children}
      </View>
    </ColorPickerContext.Provider>
  );
}

import { useState } from "react";
import {
  Platform,
  StyleSheet,
  Text,
  TextInput,
  type TextInputProps,
  View,
} from "react-native";
import Animated from "react-native-reanimated";
import { useResolveClassNames } from "uniwind";
import { useShake } from "../../hooks/use-shake";
import { EASE_OUT } from "../../styles/motion";
import {
  clamp,
  type Hsva,
  hslToHsv,
  hsvToHsl,
  parseHex,
  type Rgba,
  rgbaToHsva,
} from "./color";
import { usePickerContext } from "./context";

const SHAKE = [0, -5, 5, -3, 3, 0];

// Web draws a focus outline; the field's border shows focus instead. React
// Native's types don't list "none", but React Native Web passes it through.
const WEB_NO_OUTLINE =
  Platform.OS === "web" ? { outlineStyle: "none" as "solid" } : null;

function useFieldColors() {
  const { color: foreground } = useResolveClassNames("text-foreground");
  const { color: muted } = useResolveClassNames("text-muted");
  return { foreground, muted };
}

export type ColorPickerHexInputProps = Omit<
  TextInputProps,
  "value" | "defaultValue" | "onChangeText"
> & { className?: string };

/**
 * The hex field. It updates the color live once six or eight digits are in,
 * and shakes and reverts if what's left on submit isn't a color.
 */
export function ColorPickerHexInput({
  className = "",
  accessibilityLabel = "Hex color",
  onBlur,
  onSubmitEditing,
  style,
  ...props
}: ColorPickerHexInputProps) {
  const { hsva, hex, update, commit, disabled, reduce } = usePickerContext(
    "ColorPickerHexInput",
  );
  const { foreground, muted } = useFieldColors();
  const [draft, setDraft] = useState<string | null>(null);
  const [focused, setFocused] = useState(false);
  const { shake, style: shakeStyle } = useShake(SHAKE, 300, EASE_OUT);

  const settle = () => {
    if (draft === null) return;
    const parsed = parseHex(draft);
    if (parsed) {
      update(rgbaToHsva(parsed, hsva));
      commit();
    } else if (!reduce) {
      shake();
    }
    setDraft(null);
  };

  return (
    <Animated.View
      style={shakeStyle}
      className={`min-w-0 flex-1 flex-row items-center rounded-lg border bg-background pl-3 ${focused ? "border-border-strong" : "border-border"} ${className}`}
    >
      <Text className="text-sm text-muted">#</Text>
      <TextInput
        {...props}
        accessibilityLabel={accessibilityLabel}
        editable={!disabled}
        autoCapitalize="characters"
        autoCorrect={false}
        spellCheck={false}
        maxLength={9}
        returnKeyType="done"
        value={draft ?? hex.slice(1).toUpperCase()}
        placeholderTextColor={muted}
        onFocus={() => setFocused(true)}
        onChangeText={(text) => {
          const next = text.replace(/^#/, "");
          setDraft(next);
          // Live only at full length, so "ABC" on the way to "ABCDEF" doesn't
          // flash a short-form color.
          if (next.length === 6 || next.length === 8) {
            const parsed = parseHex(next);
            if (parsed) update(rgbaToHsva(parsed, hsva));
          }
        }}
        onBlur={(event) => {
          setFocused(false);
          settle();
          onBlur?.(event);
        }}
        onSubmitEditing={(event) => {
          settle();
          onSubmitEditing?.(event);
        }}
        style={[styles.field, { color: foreground }, WEB_NO_OUTLINE, style]}
      />
    </Animated.View>
  );
}

type ChannelSpec = {
  key: string;
  short: string;
  name: string;
  max: number;
  value: number;
  set: (n: number) => Hsva;
};

function ChannelField({ spec }: { spec: ChannelSpec }) {
  const { update, commit, disabled } = usePickerContext("ColorPickerChannels");
  const { foreground } = useFieldColors();
  const [draft, setDraft] = useState<string | null>(null);
  const [focused, setFocused] = useState(false);
  const shown = Math.round(spec.value);

  return (
    <View className="min-w-0 flex-1 items-center gap-1">
      <View
        className={`h-9 w-full justify-center rounded-lg border bg-background ${focused ? "border-border-strong" : "border-border"}`}
      >
        <TextInput
          accessibilityLabel={spec.name}
          editable={!disabled}
          keyboardType="number-pad"
          returnKeyType="done"
          maxLength={3}
          value={draft ?? String(shown)}
          onFocus={() => setFocused(true)}
          onChangeText={(text) => {
            const next = text.replace(/[^\d]/g, "").slice(0, 3);
            setDraft(next);
            if (next !== "") update(spec.set(clamp(Number(next), 0, spec.max)));
          }}
          onBlur={() => {
            setFocused(false);
            if (draft !== null) commit();
            setDraft(null);
          }}
          style={[
            styles.field,
            styles.center,
            { color: foreground },
            WEB_NO_OUTLINE,
          ]}
        />
      </View>
      <Text
        accessibilityElementsHidden
        importantForAccessibility="no"
        className="text-[11px] font-medium text-muted"
      >
        {spec.short}
      </Text>
    </View>
  );
}

export type ColorPickerChannelsProps = {
  /** Which channels to edit. Defaults to "rgb". */
  format?: "rgb" | "hsl";
  className?: string;
};

/** Numeric RGB or HSL fields, plus opacity when the picker allows alpha. */
export function ColorPickerChannels({
  format = "rgb",
  className = "",
}: ColorPickerChannelsProps) {
  const { hsva, rgba, alpha } = usePickerContext("ColorPickerChannels");
  const fromRgb = (patch: Partial<Rgba>) =>
    rgbaToHsva({ ...rgba, ...patch }, hsva);
  let specs: ChannelSpec[];
  if (format === "hsl") {
    const hsl = hsvToHsl(hsva);
    specs = [
      {
        key: "h",
        short: "H",
        name: "Hue",
        max: 360,
        value: hsl.h,
        set: (n) => hslToHsv(n, hsl.s, hsl.l, hsva, hsva.a),
      },
      {
        key: "s",
        short: "S",
        name: "Saturation",
        max: 100,
        value: hsl.s,
        set: (n) => hslToHsv(hsl.h, n, hsl.l, hsva, hsva.a),
      },
      {
        key: "l",
        short: "L",
        name: "Lightness",
        max: 100,
        value: hsl.l,
        set: (n) => hslToHsv(hsl.h, hsl.s, n, hsva, hsva.a),
      },
    ];
  } else {
    specs = [
      {
        key: "r",
        short: "R",
        name: "Red",
        max: 255,
        value: rgba.r,
        set: (n) => fromRgb({ r: n }),
      },
      {
        key: "g",
        short: "G",
        name: "Green",
        max: 255,
        value: rgba.g,
        set: (n) => fromRgb({ g: n }),
      },
      {
        key: "b",
        short: "B",
        name: "Blue",
        max: 255,
        value: rgba.b,
        set: (n) => fromRgb({ b: n }),
      },
    ];
  }
  if (alpha) {
    specs.push({
      key: "a",
      short: "A",
      name: "Opacity percent",
      max: 100,
      value: hsva.a * 100,
      set: (n) => ({ ...hsva, a: n / 100 }),
    });
  }
  return (
    <View className={`min-w-0 flex-1 flex-row gap-1.5 ${className}`}>
      {specs.map((spec) => (
        <ChannelField key={`${format}-${spec.key}`} spec={spec} />
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  field: {
    flex: 1,
    height: 34,
    fontSize: 14,
    paddingVertical: 0,
    paddingHorizontal: 6,
    textAlignVertical: "center",
    includeFontPadding: false,
    fontVariant: ["tabular-nums"],
  },
  center: { textAlign: "center" },
});

export type { Hsva, Rgba } from "./color";
export { formatHex, hsvaToRgba, parseHex, rgbaToHsva } from "./color";
export type { ColorPickerProps } from "./context";
export { ColorPicker, useColorPicker } from "./context";
export type {
  ColorPickerChannelsProps,
  ColorPickerHexInputProps,
