import {
  Children,
  type ReactNode,
  useCallback,
  useEffect,
  useState,
} from "react";
import {
  Keyboard,
  Modal,
  Platform,
  Pressable,
  type PressableProps,
  StyleSheet,
  Text,
  useWindowDimensions,
  View,
} from "react-native";
import { GestureHandlerRootView } from "react-native-gesture-handler";
import Animated, {
  cancelAnimation,
  Extrapolation,
  interpolate,
  type SharedValue,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { scheduleOnRN } from "react-native-worklets";
import { EASE_OUT } from "../../styles/motion";
import { usePickerContext } from "./context";
import { Checkerboard } from "./surfaces";

// Opening springs the panel out of the trigger's corner, quick and lightly
// damped, like a native popover. Closing runs the same path back as a short
// timed fade, so it has a fixed end: the modal is gone the moment it's done,
// and the next tap lands on the page instead of an invisible overlay.
const OPEN = { stiffness: 380, damping: 30, mass: 0.8 };
const CLOSE = { duration: 160, easing: EASE_OUT };
const REDUCED = { duration: 150 };
const PANEL_WIDTH = 288;
const GUTTER = 8;
const GAP = 8;
const EDGE = 16;
const CHIP = 24;
const CHIP_RADIUS = 6;
const KEYBOARD_SHIFT = { duration: 220, easing: EASE_OUT };

/** The on-screen keyboard's height while `active`, or 0. */
function useKeyboardHeight(active: boolean) {
  const [height, setHeight] = useState(0);
  useEffect(() => {
    if (!active) return;
    const ios = Platform.OS === "ios";
    const show = Keyboard.addListener(
      ios ? "keyboardWillShow" : "keyboardDidShow",
      (event) => setHeight(event.endCoordinates.height),
    );
    const hide = Keyboard.addListener(
      ios ? "keyboardWillHide" : "keyboardDidHide",
      () => setHeight(0),
    );
    return () => {
      show.remove();
      hide.remove();
    };
  }, [active]);
  return height;
}

export type ColorPickerTriggerProps = Omit<
  PressableProps,
  "children" | "style"
> & {
  /** Replaces the hex label beside the chip. */
  children?: ReactNode;
  className?: string;
};

/** A color chip and the hex. Opens ColorPickerContent. */
export function ColorPickerTrigger({
  children,
  className = "",
  onPress,
  accessibilityLabel,
  ...props
}: ColorPickerTriggerProps) {
  const { hex, open, setOpen, disabled, triggerRef } =
    usePickerContext("ColorPickerTrigger");
  const alpha = hex.slice(7);

  return (
    <Pressable
      {...props}
      ref={triggerRef}
      collapsable={false}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel ?? `Color, ${hex.toUpperCase()}`}
      accessibilityHint={open ? undefined : "Opens the color picker"}
      aria-expanded={open}
      aria-disabled={disabled}
      disabled={disabled}
      onPress={(event) => {
        onPress?.(event);
        if (!event.defaultPrevented) setOpen(!open);
      }}
      className={`h-11 flex-row items-center gap-2.5 self-start rounded-xl border border-border bg-background pr-3.5 pl-2.5 active:opacity-80 ${className}`}
    >
      <View style={styles.chip}>
        <Checkerboard width={CHIP} height={CHIP} />
        <View
          style={[
            StyleSheet.absoluteFill,
            styles.edge,
            { backgroundColor: hex },
          ]}
        />
      </View>
      {children ?? (
        <Text className="font-mono text-sm uppercase text-foreground tabular-nums">
          {hex.slice(0, 7)}
          {alpha ? <Text className="text-muted">{alpha}</Text> : null}
        </Text>
      )}
    </Pressable>
  );
}

/** One row of the panel, settling in just behind the one above it. */
function Row({
  index,
  progress,
  children,
}: {
  index: number;
  progress: SharedValue<number>;
  children: ReactNode;
}) {
  const style = useAnimatedStyle(() => {
    const start = index * 0.07;
    const q = interpolate(
      progress.value,
      [start, start + 0.6],
      [0, 1],
      Extrapolation.CLAMP,
    );
    return { opacity: q, transform: [{ translateY: -4 * (1 - q) }] };
  });
  return <Animated.View style={style}>{children}</Animated.View>;
}

export type ColorPickerContentProps = {
  children: ReactNode;
  /** Names the panel for screen readers. Defaults to "Color picker". */
  accessibilityLabel?: string;
  className?: string;
};

/**
 * The panel ColorPickerTrigger opens. It floats beside the trigger: below it,
 * unless there's more room above. It springs out of the trigger's corner with
 * its rows settling in behind, and folds back the same way, quicker. A tap
 * outside, or Android's back button, closes it.
 */
export function ColorPickerContent({
  children,
  accessibilityLabel = "Color picker",
  className = "",
}: ColorPickerContentProps) {
  const { open, setOpen, progress, reduce, triggerFrame } =
    usePickerContext("ColorPickerContent");
  const window = useWindowDimensions();
  const keyboard = useKeyboardHeight(open);
  const [present, setPresent] = useState(open);
  if (open && !present) setPresent(true);
  // A modal takes a moment to appear. Waiting for it, and for the panel's
  // first layout, means the opening plays where it can be seen.
  const [shown, setShown] = useState(false);
  if (!present && shown) setShown(false);
  const [panelHeight, setPanelHeight] = useState(0);
  const shift = useSharedValue(0);

  const hide = useCallback(() => setPresent(false), []);

  // onShow doesn't fire everywhere, such as on web; don't wait on it forever.
  useEffect(() => {
    if (!present || shown) return;
    const timer = setTimeout(() => setShown(true), 300);
    return () => clearTimeout(timer);
  }, [present, shown]);

  const ready = shown && panelHeight > 0;

  useEffect(() => {
    if (!present) return;
    if (open && !ready) return;
    cancelAnimation(progress);
    if (open) {
      progress.value = reduce ? withTiming(1, REDUCED) : withSpring(1, OPEN);
      return;
    }
    Keyboard.dismiss();
    progress.value = withTiming(0, reduce ? REDUCED : CLOSE, (finished) => {
      if (finished) scheduleOnRN(hide);
    });
  }, [hide, open, present, progress, ready, reduce]);

  // Side and position, from the trigger's frame.
  const width = Math.min(PANEL_WIDTH, window.width - GUTTER * 2);
  const trigger = triggerFrame ?? { x: GUTTER, y: 120, width: 0, height: 44 };
  const left = Math.min(
    Math.max(trigger.x, GUTTER),
    window.width - width - GUTTER,
  );
  const below = window.height - (trigger.y + trigger.height) - GAP - EDGE;
  const above = trigger.y - GAP - EDGE;
  const isTop = panelHeight > 0 && below < panelHeight && above > below;
  const top = isTop
    ? trigger.y - GAP - panelHeight
    : trigger.y + trigger.height + GAP;

  // When typing in a field, lift the panel clear of the keyboard.
  useEffect(() => {
    const limit = window.height - keyboard - GUTTER;
    const overflow = keyboard > 0 ? Math.max(0, top + panelHeight - limit) : 0;
    shift.value = withTiming(-overflow, KEYBOARD_SHIFT);
  }, [keyboard, panelHeight, shift, top, window.height]);

  // The panel grows from the corner nearest the trigger's chip.
  const panelStyle = useAnimatedStyle(() => {
    const p = progress.value;
    const settled = Math.min(1, Math.max(0, p));
    return {
      opacity: interpolate(p, [0, 0.5], [0, 1], Extrapolation.CLAMP),
      transform: [
        { translateY: shift.value + (isTop ? 8 : -8) * (1 - settled) },
        { scale: reduce ? 1 : 0.9 + 0.1 * p },
      ],
    };
  });

  let row = 0;
  const rows = Children.map(children, (child) => {
    const index = row;
    row += 1;
    return (
      <Row index={index} progress={progress}>
        {child}
      </Row>
    );
  });

  return (
    <Modal
      transparent
      visible={present}
      animationType="none"
      statusBarTranslucent
      navigationBarTranslucent
      onShow={() => setShown(true)}
      onRequestClose={() => setOpen(false)}
    >
      {/* Gestures inside a modal need their own root on Android. */}
      <GestureHandlerRootView style={styles.root}>
        <Pressable
          accessibilityLabel="Close"
          accessibilityRole="button"
          style={StyleSheet.absoluteFill}
          onPress={() => setOpen(false)}
        />
        <Animated.View
          accessibilityViewIsModal
          accessibilityLabel={accessibilityLabel}
          onLayout={({ nativeEvent }) =>
            setPanelHeight(nativeEvent.layout.height)
          }
          className={`gap-3 rounded-2xl border border-border bg-background p-3 ${className}`}
          style={[
            styles.panel,
            { left, top, width },
            isTop ? styles.fromBottom : styles.fromTop,
            panelStyle,
          ]}
        >
          {rows}
        </Animated.View>
      </GestureHandlerRootView>
    </Modal>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  panel: {
    position: "absolute",
    boxShadow: "0 12px 32px -8px rgba(0, 0, 0, 0.25)",
  },
  // The corner nearest the trigger's chip, at the panel's left edge.
  fromTop: { transformOrigin: "24px 0px" },
  fromBottom: { transformOrigin: "24px 100%" },
  chip: {
    width: CHIP,
    height: CHIP,
    borderRadius: CHIP_RADIUS,
    overflow: "hidden",
  },
  edge: {
    borderRadius: CHIP_RADIUS,
    borderWidth: 1,
    borderColor: "rgba(0, 0, 0, 0.1)",
  },
});

import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import { Pressable, StyleSheet, View } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { useResolveClassNames } from "uniwind";
import { SPRING_LAYOUT, SPRING_PRESS } from "../../styles/motion";
import { formatHex, parseHex, rgbaToHsva } from "./color";
import { usePickerContext } from "./context";
import { Checkerboard } from "./surfaces";

const SIZE = 24;
const RING_GAP = 3;
// The ring hops between swatches over a low arc, higher the further it goes.
const HOP = 0.15;

type Spot = { x: number; y: number };

const PresetsContext = createContext<{
  place: (value: string, spot: Spot) => void;
} | null>(null);

export type ColorPickerPresetsProps = {
  children: ReactNode;
  /** Names the group for screen readers, such as "Presets". */
  accessibilityLabel?: string;
  className?: string;
};

/** A row of preset swatches. A ring marks the one matching the current color. */
export function ColorPickerPresets({
  children,
  accessibilityLabel,
  className = "",
}: ColorPickerPresetsProps) {
  const { hex, reduce } = usePickerContext("ColorPickerPresets");
  // On web, borders resolve per side.
  const ringClass = useResolveClassNames("border-foreground/70");
  const ring = ringClass.borderColor ?? ringClass.borderTopColor;
  const spots = useRef(new Map<string, Spot>());
  const [version, setVersion] = useState(0);
  const place = useCallback((value: string, spot: Spot) => {
    const known = spots.current.get(value);
    if (known && known.x === spot.x && known.y === spot.y) return;
    spots.current.set(value, spot);
    setVersion((n) => n + 1);
  }, []);

  const from = useSharedValue<Spot>({ x: 0, y: 0 });
  const to = useSharedValue<Spot>({ x: 0, y: 0 });
  const travel = useSharedValue(1);
  const shown = useSharedValue(0);
  const last = useRef<Spot | null>(null);

  useEffect(() => {
    const target = spots.current.get(hex);
    if (!target) {
      shown.value = withTiming(0, { duration: 120 });
      last.current = null;
      return;
    }
    const start = last.current;
    last.current = target;
    if (!start || reduce) {
      from.value = target;
      to.value = target;
      travel.value = 1;
      shown.value = withTiming(1, { duration: 120 });
      return;
    }
    if (start.x === target.x && start.y === target.y) return;
    from.value = start;
    to.value = target;
    travel.value = 0;
    travel.value = withSpring(1, SPRING_LAYOUT);
    shown.value = 1;
  }, [from, hex, reduce, shown, to, travel, version]);

  const ringStyle = useAnimatedStyle(() => {
    const t = travel.value;
    const a = from.value;
    const b = to.value;
    const distance = Math.hypot(b.x - a.x, b.y - a.y);
    const arc =
      HOP * distance * Math.sin(Math.PI * Math.min(1, Math.max(0, t)));
    return {
      opacity: shown.value,
      transform: [
        { translateX: a.x + (b.x - a.x) * t - RING_GAP },
        { translateY: a.y + (b.y - a.y) * t - RING_GAP - arc },
      ],
    };
  });

  return (
    <PresetsContext.Provider value={{ place }}>
      <View
        accessibilityLabel={accessibilityLabel}
        className={`flex-row flex-wrap gap-2 ${className}`}
      >
        {children}
        <Animated.View
          pointerEvents="none"
          style={[styles.ring, { borderColor: ring }, ringStyle]}
        />
      </View>
    </PresetsContext.Provider>
  );
}

export type ColorPickerPresetProps = {
  /** The hex color this preset applies. */
  value: string;
  /** The color's name for screen readers. Defaults to the hex. */
  label?: string;
  onPress?: () => void;
  className?: string;
};

export function ColorPickerPreset({
  value,
  label,
  onPress,
  className = "",
}: ColorPickerPresetProps) {
  const { hsva, hex, update, commit, disabled, reduce } =
    usePickerContext("ColorPickerPreset");
  const presets = useContext(PresetsContext);
  const parsed = parseHex(value);
  const normalized = parsed ? formatHex(parsed) : value;
  const selected = normalized === hex;
  const scale = useSharedValue(1);
  const pressStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={label ?? normalized}
      accessibilityState={{ selected, disabled }}
      disabled={disabled}
      hitSlop={6}
      onLayout={({ nativeEvent }) =>
        presets?.place(normalized, {
          x: nativeEvent.layout.x,
          y: nativeEvent.layout.y,
        })
      }
      onPressIn={() => {
        if (!reduce) scale.value = withSpring(0.88, SPRING_PRESS);
      }}
      onPressOut={() => {
        scale.value = withSpring(1, SPRING_PRESS);
      }}
      onPress={() => {
        onPress?.();
        if (!parsed) return;
        update(rgbaToHsva(parsed, hsva));
        commit();
      }}
      className={className}
    >
      <Animated.View style={[styles.swatch, pressStyle]}>
        <Checkerboard width={SIZE} height={SIZE} />
        <View style={[styles.color, { backgroundColor: normalized }]} />
      </Animated.View>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  swatch: {
    width: SIZE,
    height: SIZE,
    borderRadius: SIZE / 2,
    overflow: "hidden",
  },
  color: {
    ...StyleSheet.absoluteFill,
    borderRadius: SIZE / 2,
    borderWidth: 1,
    borderColor: "rgba(0, 0, 0, 0.1)",
  },
  ring: {
    position: "absolute",
    left: 0,
    top: 0,
    width: SIZE + RING_GAP * 2,
    height: SIZE + RING_GAP * 2,
    borderRadius: (SIZE + RING_GAP * 2) / 2,
    borderWidth: 2,
  },
});

import { memo, useEffect, useRef } from "react";
import {
  type AccessibilityActionEvent,
  Platform,
  StyleSheet,
  View,
  type ViewProps,
} from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  type SharedValue,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { scheduleOnRN } from "react-native-worklets";
import { EASE_OUT, SPRING_GLIDE, SPRING_PRESS } from "../../styles/motion";
import { hueColor, rgbaString } from "./color";
import { usePickerContext } from "./context";

// The loupe lifts with a visible overshoot so it reads as picked up, unlike
// the critically damped glide the thumb itself rides on.
const LOUPE_LIFT = { stiffness: 520, damping: 24, mass: 0.6 };
const LOUPE_DROP = { duration: 120, easing: EASE_OUT };
// Drag speed, in track widths per second, swings the loupe like a pendulum.
const LOUPE_TILT = 16;
const LOUPE_TILT_SPEED = 4;
const THUMB = 18;
// Sliders inset the thumb's path by half a thumb, so it never leaves the track.
const RAIL_INSET = THUMB / 2;
const CHECK = 4;
const CHECK_LIGHT = "#fafafa";
const CHECK_DARK = "#d4d4d8";

/** A gradient fill, through experimental_backgroundImage on native. */
export function gradient(css: string) {
  return Platform.OS === "web"
    ? ({ backgroundImage: css } as object)
    : { experimental_backgroundImage: css };
}

/**
 * The transparency checkerboard. React Native has no conic gradient, so it's
 * drawn from small squares, once per size.
 */
export const Checkerboard = memo(function Checkerboard({
  width,
  height,
}: {
  width: number;
  height: number;
}) {
  const columns = Math.ceil(width / CHECK);
  const rows = Math.ceil(height / CHECK);
  const squares: { left: number; top: number }[] = [];
  for (let row = 0; row < rows; row++) {
    for (let column = row % 2; column < columns; column += 2) {
      squares.push({ left: column * CHECK, top: row * CHECK });
    }
  }
  return (
    <View
      pointerEvents="none"
      style={[StyleSheet.absoluteFill, { backgroundColor: CHECK_LIGHT }]}
    >
      {squares.map(({ left, top }) => (
        <View key={`${left}-${top}`} style={[styles.check, { left, top }]} />
      ))}
    </View>
  );
});

/** Where a touch lands on a track, kept on the UI thread while dragging. */
function useTrack({
  axes,
  inset,
  onPoint,
  onEnd,
  disabled,
}: {
  axes: "x" | "xy";
  inset: number;
  onPoint: (x: number, y: number) => void;
  onEnd: () => void;
  disabled: boolean;
}) {
  const width = useSharedValue(0);
  const height = useSharedValue(0);
  const x = useSharedValue(0);
  const y = useSharedValue(0);
  const dragging = useSharedValue(false);
  const lift = useSharedValue(0);
  const tilt = useSharedValue(0);

  const place = (px: number, py: number) => {
    "worklet";
    const span = Math.max(1, width.value - inset * 2);
    const nx = Math.min(1, Math.max(0, (px - inset) / span));
    const ny =
      axes === "xy"
        ? Math.min(1, Math.max(0, py / Math.max(1, height.value)))
        : 0;
    x.value = nx;
    y.value = ny;
    scheduleOnRN(onPoint, nx, ny);
  };

  // A finger down jumps the thumb there; moving drags it.
  const gesture = Gesture.Pan()
    .enabled(!disabled)
    .minDistance(0)
    .onBegin((event) => {
      dragging.value = true;
      lift.value = withSpring(1, LOUPE_LIFT);
      place(event.x, event.y);
    })
    .onUpdate((event) => {
      place(event.x, event.y);
      const speed = event.velocityX / Math.max(1, width.value);
      tilt.value = withSpring(
        Math.max(-1, Math.min(1, speed / LOUPE_TILT_SPEED)) * -LOUPE_TILT,
        SPRING_PRESS,
      );
    })
    .onFinalize(() => {
      dragging.value = false;
      lift.value = withTiming(0, LOUPE_DROP);
      tilt.value = withSpring(0, SPRING_PRESS);
      scheduleOnRN(onEnd);
    });

  return { gesture, width, height, x, y, dragging, lift, tilt };
}

/** Thumbs follow the color when it changes from elsewhere, gliding there. */
function useFollow(
  shared: SharedValue<number>,
  target: number,
  dragging: SharedValue<boolean>,
  reduce: boolean,
) {
  useEffect(() => {
    if (dragging.value) return;
    shared.value = reduce ? target : withSpring(target, SPRING_GLIDE);
  }, [dragging, reduce, shared, target]);
}

function Thumb({
  x,
  y,
  width,
  height,
  inset,
  lift,
  tilt,
  color,
  reduce,
}: {
  x: SharedValue<number>;
  y?: SharedValue<number>;
  width: SharedValue<number>;
  height: SharedValue<number>;
  inset: number;
  lift: SharedValue<number>;
  tilt: SharedValue<number>;
  color: string;
  reduce: boolean;
}) {
  const position = useAnimatedStyle(() => {
    const span = Math.max(0, width.value - inset * 2);
    return {
      transform: [
        { translateX: inset + x.value * span - THUMB / 2 },
        {
          translateY: y
            ? y.value * height.value - THUMB / 2
            : height.value / 2 - THUMB / 2,
        },
      ],
    };
  });
  // The thumb tucks in while the loupe is up, so the finger's color shows above.
  const dot = useAnimatedStyle(() => ({
    transform: [{ scale: reduce ? 1 : 1 - 0.22 * lift.value }],
  }));
  const loupe = useAnimatedStyle(() => {
    const l = reduce ? 0 : lift.value;
    return {
      opacity: Math.min(1, Math.max(0, l)),
      transform: [
        { translateY: 16 * (1 - l) },
        { rotate: `${tilt.value}deg` },
        { scale: 0.3 + 0.7 * l },
      ],
    };
  });

  return (
    <Animated.View pointerEvents="none" style={[styles.thumbSlot, position]}>
      <Animated.View style={[styles.loupe, loupe]}>
        {/* A teardrop: a square with one sharp corner, turned to point down.
            The color is the drop's own background, which follows its mixed
            corners; iOS wouldn't clip a filled child to them. */}
        <View style={[styles.drop, { backgroundColor: color }]} />
      </Animated.View>
      <Animated.View style={[styles.dot, { backgroundColor: color }, dot]} />
    </Animated.View>
  );
}

export type ColorPickerAreaProps = Omit<ViewProps, "children"> & {
  /** Accessible name. Defaults to "Saturation and brightness". */
  label?: string;
  className?: string;
};

/**
 * The saturation and brightness area. Drag anywhere; a loupe lifts above the
 * finger to show the color under it.
 */
export function ColorPickerArea({
  label = "Saturation and brightness",
  className = "",
  style,
  ...props
}: ColorPickerAreaProps) {
  const { hsva, rgba, update, commit, disabled, reduce } =
    usePickerContext("ColorPickerArea");
  const latest = useRef(hsva);
  latest.current = hsva;

  const track = useTrack({
    axes: "xy",
    inset: 0,
    onPoint: (x, y) =>
      update({ ...latest.current, s: x * 100, v: (1 - y) * 100 }),
    onEnd: commit,
    disabled,
  });
  useFollow(track.x, hsva.s / 100, track.dragging, reduce);
  useFollow(track.y, 1 - hsva.v / 100, track.dragging, reduce);

  const s = Math.round(hsva.s);
  const v = Math.round(hsva.v);
  const nudge = (event: AccessibilityActionEvent) => {
    const step = 5;
    const name = event.nativeEvent.actionName;
    const next =
      name === "increment"
        ? { ...hsva, s: hsva.s + step }
        : name === "decrement"
          ? { ...hsva, s: hsva.s - step }
          : name === "brighter"
            ? { ...hsva, v: hsva.v + step }
            : { ...hsva, v: hsva.v - step };
    update(next);
    commit();
  };

  return (
    <GestureDetector gesture={track.gesture}>
      <Animated.View
        {...props}
        accessible
        accessibilityRole="adjustable"
        accessibilityLabel={label}
        aria-valuetext={`Saturation ${s}%, brightness ${v}%`}
        accessibilityActions={[
          { name: "increment", label: "More saturated" },
          { name: "decrement", label: "Less saturated" },
          { name: "brighter", label: "Brighter" },
          { name: "darker", label: "Darker" },
        ]}
        onAccessibilityAction={nudge}
        onLayout={(event) => {
          track.width.value = event.nativeEvent.layout.width;
          track.height.value = event.nativeEvent.layout.height;
          props.onLayout?.(event);
        }}
        className={`h-40 w-full rounded-xl ${className}`}
        style={[{ backgroundColor: hueColor(hsva.h) }, style]}
      >
        <View
          pointerEvents="none"
          style={[
            styles.fill,
            styles.areaRound,
            gradient(
              "linear-gradient(to right, rgba(255, 255, 255, 1), rgba(255, 255, 255, 0))",
            ),
          ]}
        />
        <View
          pointerEvents="none"
          style={[
            styles.fill,
            styles.areaRound,
            gradient(
              "linear-gradient(to top, rgba(0, 0, 0, 1), rgba(0, 0, 0, 0))",
            ),
          ]}
        />
        <View
          pointerEvents="none"
          style={[styles.fill, styles.areaRound, styles.inset]}
        />
        <Thumb
          x={track.x}
          y={track.y}
          width={track.width}
          height={track.height}
          inset={0}
          lift={track.lift}
          tilt={track.tilt}
          color={rgbaString(rgba, 1)}
          reduce={reduce}
        />
      </Animated.View>
    </GestureDetector>
  );
}

function ChannelSlider({
  value,
  max,
  onValue,
  label,
  valueText,
  background,
  thumbColor,
  checker = false,
  className = "",
}: {
  value: number;
  max: number;
  onValue: (next: number) => void;
  label: string;
  valueText: string;
  background: string;
  thumbColor: string;
  checker?: boolean;
  className?: string;
}) {
  const { commit, disabled, reduce } = usePickerContext("ColorPicker slider");
  const track = useTrack({
    axes: "x",
    inset: RAIL_INSET,
    onPoint: (x) => onValue(x * max),
    onEnd: commit,
    disabled,
  });
  useFollow(track.x, value / max, track.dragging, reduce);
  const widthRef = useRef(0);

  return (
    <GestureDetector gesture={track.gesture}>
      <View
        accessible
        accessibilityRole="adjustable"
        accessibilityLabel={label}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={Math.round(value)}
        aria-valuetext={valueText}
        accessibilityActions={[{ name: "increment" }, { name: "decrement" }]}
        onAccessibilityAction={(event) => {
          const step = Math.max(1, Math.round(max / 36));
          onValue(
            value +
              (event.nativeEvent.actionName === "increment" ? step : -step),
          );
          commit();
        }}
        onLayout={(event) => {
          widthRef.current = event.nativeEvent.layout.width;
          track.width.value = event.nativeEvent.layout.width;
          track.height.value = event.nativeEvent.layout.height;
        }}
        // A tall touch area around a thin track.
        hitSlop={{ top: 12, bottom: 12 }}
        className={`h-3.5 w-full rounded-full ${className}`}
      >
        <View style={[styles.fill, styles.round, styles.clip]}>
          {checker ? <Checkerboard width={320} height={14} /> : null}
          <View style={[styles.fill, gradient(background)]} />
          <View style={[styles.fill, styles.round, styles.inset]} />
        </View>
        <Thumb
          x={track.x}
          width={track.width}
          height={track.height}
          inset={RAIL_INSET}
          lift={track.lift}
          tilt={track.tilt}
          color={thumbColor}
          reduce={reduce}
        />
      </View>
    </GestureDetector>
  );
}

export type ColorPickerSliderProps = { label?: string; className?: string };

export function ColorPickerHue({
  label = "Hue",
  className,
}: ColorPickerSliderProps) {
  const { hsva, update } = usePickerContext("ColorPickerHue");
  const latest = useRef(hsva);
  latest.current = hsva;
  return (
    <ChannelSlider
      value={hsva.h}
      max={360}
      onValue={(next) => update({ ...latest.current, h: next })}
      label={label}
      valueText={`${Math.round(hsva.h)} degrees`}
      background="linear-gradient(to right, #ff0000 0%, #ffff00 17%, #00ff00 33%, #00ffff 50%, #0000ff 67%, #ff00ff 83%, #ff0000 100%)"
      thumbColor={hueColor(hsva.h)}
      className={className}
    />
  );
}

/** Renders nothing when the picker has `alpha={false}`. */
export function ColorPickerAlpha({
  label = "Opacity",
  className,
}: ColorPickerSliderProps) {
  const { hsva, rgba, alpha, update } = usePickerContext("ColorPickerAlpha");
  const latest = useRef(hsva);
  latest.current = hsva;
  if (!alpha) return null;
  return (
    <ChannelSlider
      value={hsva.a * 100}
      max={100}
      onValue={(next) =>
        update({ ...latest.current, a: Math.round(next) / 100 })
      }
      label={label}
      valueText={`${Math.round(hsva.a * 100)}%`}
      background={`linear-gradient(to right, ${rgbaString(rgba, 0)}, ${rgbaString(rgba, 1)})`}
      thumbColor={rgbaString(rgba)}
      checker
      className={className}
    />
  );
}

/** The current color over a transparency checkerboard. Decorative. */
export function ColorPickerSwatch({ className = "" }: { className?: string }) {
  const { hex } = usePickerContext("ColorPickerSwatch");
  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      className={`size-9 overflow-hidden rounded-lg ${className}`}
    >
      <Checkerboard width={36} height={36} />
      <View
        style={[
          styles.fill,
          styles.inset,
          styles.swatchRound,
          { backgroundColor: hex },
        ]}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  fill: { ...StyleSheet.absoluteFill },
  round: { borderRadius: 999 },
  clip: { overflow: "hidden" },
  // A faint inner edge so light colors don't melt into the panel.
  inset: { borderWidth: 1, borderColor: "rgba(0, 0, 0, 0.1)" },
  areaRound: { borderRadius: 12 },
  swatchRound: { borderRadius: 8 },
  check: {
    position: "absolute",
    width: CHECK,
    height: CHECK,
    backgroundColor: CHECK_DARK,
  },
  thumbSlot: {
    position: "absolute",
    left: 0,
    top: 0,
    width: THUMB,
    height: THUMB,
  },
  dot: {
    width: THUMB,
    height: THUMB,
    borderRadius: THUMB / 2,
    borderWidth: 3,
    borderColor: "#ffffff",
    boxShadow: "0 0 0 1px rgba(0, 0, 0, 0.12), 0 2px 6px rgba(0, 0, 0, 0.25)",
  },
  loupe: {
    position: "absolute",
    left: THUMB / 2 - 20,
    bottom: THUMB + 12,
    width: 40,
    height: 40,
    transformOrigin: "50% 130%",
  },
  drop: {
    width: 40,
    height: 40,
    borderWidth: 3,
    borderColor: "#ffffff",
    borderTopLeftRadius: 20,
    borderTopRightRadius: 20,
    borderBottomRightRadius: 20,
    borderBottomLeftRadius: 0,
    transform: [{ rotate: "-45deg" }],
    boxShadow: "0 0 0 1px rgba(0, 0, 0, 0.1), 0 6px 16px rgba(0, 0, 0, 0.28)",
  },
});

