import { useEffect, useRef, useState } from "react";
import { Text, type TextProps } from "react-native";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { EASE_OUT } from "../../styles/motion";
import { glyphStyles } from "./use-glyph-cell";

const ease = EASE_OUT.factory();

export type AnimatedNumberProps = Omit<TextProps, "children"> & {
  value: number;
  /** Count duration in milliseconds. Defaults to 1200. */
  duration?: number;
  /** Formats each frame. Defaults to a rounded, locale-grouped integer. */
  format?: (value: number) => string;
  /** Disables counting independently of the system preference. */
  disableAnimation?: boolean;
  className?: string;
};

const defaultFormat = (value: number) => Math.round(value).toLocaleString();

/** Counts from the previous value (0 at first) to `value` on beUI's ease-out curve. */
export function AnimatedNumber({
  value,
  duration = 1200,
  format = defaultFormat,
  disableAnimation = false,
  className = "",
  style,
  accessibilityLabel,
  ...props
}: AnimatedNumberProps) {
  const reducedMotion = useReducedMotionPreference();
  const animate = !reducedMotion && !disableAnimation;
  const [display, setDisplay] = useState(animate ? 0 : value);
  const current = useRef(animate ? 0 : value);

  useEffect(() => {
    if (!animate) {
      current.current = value;
      setDisplay(value);
      return;
    }
    // Continue from wherever an interrupted count stopped.
    const start = current.current;
    const startedAt = Date.now();
    let frame = 0;
    const tick = () => {
      const t = Math.min(1, (Date.now() - startedAt) / duration);
      const next = start + (value - start) * ease(t);
      current.current = next;
      setDisplay(next);
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [animate, duration, value]);

  return (
    <Text
      {...props}
      // Screen readers get the final value rather than every frame.
      accessibilityLabel={accessibilityLabel ?? format(value)}
      className={className}
      style={[glyphStyles.tabular, style]}
    >
      {format(display)}
    </Text>
  );
}

export type { AnimatedNumberProps } from "./animated-number";
export { AnimatedNumber } from "./animated-number";
export type { NumberTickerProps } from "./number-ticker";
export { NumberTicker } from "./number-ticker";

import { useEffect, useMemo, useState } from "react";
import { StyleSheet, Text, View, type ViewProps } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withTiming,
} from "react-native-reanimated";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { EASE_OUT } from "../../styles/motion";
import { type GlyphCell, glyphStyles, useGlyphCell } from "./use-glyph-cell";

const DIGITS = Array.from({ length: 10 }, (_, digit) => digit);

export type NumberTickerProps = Omit<ViewProps, "children"> & {
  value: number;
  /** Pads with leading zeros to this many digits. */
  pad?: number;
  /** Per-digit roll duration in milliseconds. Defaults to 900. */
  duration?: number;
  /** Delay between digits on the first reveal, in milliseconds. Defaults to 40. */
  stagger?: number;
  prefix?: string;
  suffix?: string;
  /** Inserts locale group separators. */
  locale?: boolean;
  /** Custom formatter for the rounded value. */
  format?: (value: number) => string;
  /** Disables rolling independently of the system preference. */
  disableAnimation?: boolean;
  /** Text style for every glyph, such as `text-3xl font-semibold`. */
  className?: string;
  /** Extra classes for digit columns only. */
  digitClassName?: string;
};

function DigitColumn({
  digit,
  delay,
  duration,
  cell,
  className,
  reduce,
}: {
  digit: number;
  delay: number;
  duration: number;
  cell: GlyphCell;
  className: string;
  reduce: boolean;
}) {
  const offset = useSharedValue(0);

  useEffect(() => {
    const target = -digit * cell.height;
    offset.value = reduce
      ? target
      : withDelay(delay, withTiming(target, { duration, easing: EASE_OUT }));
  }, [cell.height, delay, digit, duration, offset, reduce]);

  const columnStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: offset.value }],
  }));

  return (
    <View style={[styles.window, { width: cell.width, height: cell.height }]}>
      <Animated.View style={[styles.column, columnStyle]}>
        {DIGITS.map((n) => (
          <Text
            key={n}
            className={className}
            style={[glyphStyles.tabular, { height: cell.height }]}
          >
            {n}
          </Text>
        ))}
      </Animated.View>
    </View>
  );
}

/** Each digit rolls through a 0–9 column to its new value. */
export function NumberTicker({
  value,
  pad,
  duration = 900,
  stagger = 40,
  prefix,
  suffix,
  locale = false,
  format,
  disableAnimation = false,
  className = "",
  digitClassName = "",
  accessibilityLabel,
  ...props
}: NumberTickerProps) {
  const reducedMotion = useReducedMotionPreference();
  const reduce = reducedMotion || disableAnimation;
  const { cell, measurer } = useGlyphCell(className);
  const [entered, setEntered] = useState(false);

  const text = useMemo(() => {
    const rounded = Math.round(value);
    const formatted = format
      ? format(rounded)
      : locale
        ? rounded.toLocaleString()
        : String(rounded);
    return pad ? formatted.padStart(pad, "0") : formatted;
  }, [format, locale, pad, value]);

  // Key glyphs by place value from the right, so a changing digit keeps its
  // column and rolls instead of remounting, and growth adds columns on the left.
  const glyphs = Array.from(text, (char, index) => ({
    char,
    id: `place-${text.length - 1 - index}`,
  }));

  // The stagger is an entrance flourish; later updates roll every digit at once.
  useEffect(() => {
    if (!cell || entered) return;
    const timer = setTimeout(
      () => setEntered(true),
      duration + glyphs.length * stagger,
    );
    return () => clearTimeout(timer);
  }, [cell, duration, entered, glyphs.length, stagger]);

  return (
    <View
      {...props}
      accessible
      accessibilityRole="text"
      accessibilityLabel={
        accessibilityLabel ?? `${prefix ?? ""}${text}${suffix ?? ""}`
      }
      style={[styles.row, props.style]}
    >
      {measurer}
      {prefix ? <Text className={className}>{prefix}</Text> : null}
      {cell ? (
        glyphs.map(({ char, id }, index) =>
          /\d/.test(char) ? (
            <DigitColumn
              key={id}
              digit={Number(char)}
              delay={entered ? 0 : index * stagger}
              duration={duration}
              cell={cell}
              className={`${className} ${digitClassName}`}
              reduce={reduce}
            />
          ) : (
            <Text key={id} className={className}>
              {char}
            </Text>
          ),
        )
      ) : (
        // Hold the space with plain text until the digit cell is measured.
        <Text className={className} style={styles.hidden}>
          {text}
        </Text>
      )}
      {suffix ? <Text className={className}>{suffix}</Text> : null}
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: "row", alignItems: "center", alignSelf: "flex-start" },
  window: { overflow: "hidden" },
  column: { position: "absolute", left: 0, right: 0, top: 0 },
  hidden: { opacity: 0 },
});

import { useState } from "react";
import { StyleSheet, Text, View } from "react-native";

export type GlyphCell = { width: number; height: number };

/**
 * Measures one tabular "0" in the caller's text style, giving the fixed cell
 * that rolling glyphs travel through. Render `measurer` once inside the
 * component; `cell` stays null until the first layout.
 */
export function useGlyphCell(className: string) {
  const [cell, setCell] = useState<GlyphCell | null>(null);

  const measurer = (
    <View style={glyphStyles.probe}>
      <Text
        className={className}
        style={glyphStyles.tabular}
        onLayout={({ nativeEvent: { layout } }) => {
          setCell((current) =>
            current?.width === layout.width && current.height === layout.height
              ? current
              : { width: layout.width, height: layout.height },
          );
        }}
      >
        0
      </Text>
    </View>
  );

  return { cell, measurer };
}

export const glyphStyles = StyleSheet.create({
  tabular: { fontVariant: ["tabular-nums"] },
  // Wide and invisible so the probe always lays out at its natural size.
  probe: {
    position: "absolute",
    left: 0,
    top: 0,
    width: 10000,
    flexDirection: "row",
    alignItems: "flex-start",
    opacity: 0,
    pointerEvents: "none",
  },
});

