import { useEffect, useRef, useState } from "react";
import { StyleSheet, Text, View, type ViewProps } from "react-native";
import Animated, {
  cancelAnimation,
  interpolateColor,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withTiming,
} from "react-native-reanimated";
import { useResolveClassNames } from "uniwind";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { GlyphRow } from "../../primitives/glyph-row";
import { EASE_IN_OUT, EASE_OUT } from "../../styles/motion";

const PALETTE = ["#60a5fa", "#818cf8", "#c084fc", "#fb7185", "#fbbf24"];
// The colored trail spans 14% of the word either side of the sweep.
const TRAIL = 0.14;
const SWEEP_START = -TRAIL;
const SWEEP_END = 1 + TRAIL;

export type ChromaticTextRevealProps = Omit<ViewProps, "children"> & {
  /** Fixed sentence fragment before the changing word. */
  prefix: string;
  /** Words revealed one after another after the prefix. */
  words: string[];
  /** Colors along the moving chromatic edge. */
  colors?: string[];
  /** Sweep duration in milliseconds. Defaults to 1200. */
  duration?: number;
  /** Delay before each sweep in milliseconds. */
  delay?: number;
  /** Rest after a word finishes revealing, in milliseconds. Defaults to 800. */
  pauseDuration?: number;
  /** Returns to the first word after the last. Defaults to true. */
  loop?: boolean;
  /** Text style for the whole sentence, such as `text-3xl font-semibold`. */
  className?: string;
  /** Disables sweeping and cycling independently of the system preference. */
  disableAnimation?: boolean;
};

function Word({
  word,
  className,
  palette,
  foreground,
  duration,
  delay,
  reduce,
  onRevealed,
}: {
  word: string;
  className: string;
  palette: string[];
  foreground: string;
  duration: number;
  delay: number;
  reduce: boolean;
  onRevealed: () => void;
}) {
  const sweep = useSharedValue(reduce ? SWEEP_END : SWEEP_START);
  // A ref keeps a new callback identity from restarting the sweep.
  const revealedRef = useRef(onRevealed);
  revealedRef.current = onRevealed;
  const enter = useSharedValue(reduce ? 1 : 0);

  useEffect(() => {
    if (reduce) return;
    enter.value = withTiming(1, { duration: 360, easing: EASE_OUT });
    sweep.value = withDelay(
      delay,
      withTiming(SWEEP_END, { duration, easing: EASE_IN_OUT }),
    );
    const timer = setTimeout(() => revealedRef.current(), delay + duration);
    return () => {
      clearTimeout(timer);
      cancelAnimation(sweep);
    };
  }, [delay, duration, enter, reduce, sweep]);

  const stops = palette.map((_, index) =>
    palette.length === 1
      ? 0
      : -TRAIL + (index / (palette.length - 1)) * TRAIL * 2,
  );

  // Behind the sweep the word is solid; inside the trail it takes the palette;
  // ahead of it the word is still invisible.
  const colorAt = (s: number, position: number) => {
    "worklet";
    const offset = position - s;
    if (offset < -TRAIL) return { color: foreground, opacity: 1 };
    if (offset > TRAIL) return { color: foreground, opacity: 0 };
    return {
      color:
        palette.length === 1
          ? (palette[0] ?? foreground)
          : interpolateColor(offset, stops, palette),
      opacity: 1,
    };
  };

  const enterStyle = useAnimatedStyle(() => ({
    opacity: 0.56 + 0.44 * Math.min(1, enter.value * (360 / 280)),
    transform: [{ translateY: 5 * (1 - enter.value) }],
  }));

  return (
    <Animated.View style={[styles.word, enterStyle]}>
      <GlyphRow
        text={word}
        className={className}
        progress={sweep}
        colorAt={colorAt}
      />
    </Animated.View>
  );
}

/** A sentence whose final word is revealed by a moving chromatic sweep, then cycles. */
export function ChromaticTextReveal({
  prefix,
  words,
  colors = PALETTE,
  duration = 1200,
  delay = 0,
  pauseDuration = 800,
  loop = true,
  className = "",
  disableAnimation = false,
  accessibilityLabel,
  ...props
}: ChromaticTextRevealProps) {
  const reducedMotion = useReducedMotionPreference();
  const reduce = reducedMotion || disableAnimation;
  const { color: foreground } = useResolveClassNames("text-foreground");
  const [index, setIndex] = useState(0);
  const [cycle, setCycle] = useState(0);
  const palette = colors.length > 0 ? colors : PALETTE;
  const active = words.length > 0 ? index % words.length : 0;
  const word = words[active] ?? "";
  const sizing = Array.from(new Set(words));

  const [revealed, setRevealed] = useState(false);

  useEffect(() => {
    if (!revealed) return;
    const last = active === words.length - 1;
    if (reduce || words.length < 2 || (last && !loop)) return;
    const timer = setTimeout(() => {
      setRevealed(false);
      setIndex((current) => (current + 1) % words.length);
      setCycle((current) => current + 1);
    }, pauseDuration);
    return () => clearTimeout(timer);
  }, [active, loop, pauseDuration, reduce, revealed, words.length]);

  return (
    <View
      {...props}
      accessible
      accessibilityRole="text"
      accessibilityLabel={accessibilityLabel ?? `${prefix} ${word}`}
      style={[styles.sentence, props.style]}
    >
      <Text className={className}>
        {prefix}
        {words.length > 0 ? " " : null}
      </Text>
      {words.length > 0 ? (
        <View>
          {/* The widest word reserves space so the sentence never reflows. */}
          {sizing.map((candidate) => (
            <Text key={candidate} className={className} style={styles.sizer}>
              {candidate}
            </Text>
          ))}
          <Word
            key={`${word}-${cycle}`}
            word={word}
            className={className}
            palette={palette}
            foreground={String(foreground ?? "black")}
            duration={duration}
            delay={delay}
            reduce={reduce}
            onRevealed={() => setRevealed(true)}
          />
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  sentence: {
    flexDirection: "row",
    alignItems: "flex-start",
    alignSelf: "flex-start",
  },
  // Stacked invisibly in one cell; the tallest and widest sets the size.
  sizer: { opacity: 0, height: 0, overflow: "hidden" },
  word: { position: "absolute", left: 0, top: 0 },
});

export type { ChromaticTextRevealProps } from "./chromatic-text-reveal";
export { ChromaticTextReveal } from "./chromatic-text-reveal";
export type { TextCascadeProps } from "./text-cascade";
export { TextCascade } from "./text-cascade";
export type { TextRevealProps } from "./text-reveal";
export { TextReveal } from "./text-reveal";
export type { TextScrambleProps } from "./text-scramble";
export { TextScramble } from "./text-scramble";
export type { TextShimmerProps } from "./text-shimmer";
export { TextShimmer } from "./text-shimmer";

import { View, type ViewProps } from "react-native";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { CascadeText } from "../../primitives/cascade-text";

export type TextCascadeProps = Omit<ViewProps, "children"> & {
  /** Current text. Changing it cascades the letters to the new value. */
  text: string;
  /** Text style for every letter. */
  className?: string;
  /** Disables the cascade independently of the system preference. */
  disableAnimation?: boolean;
};

/**
 * Letter-by-letter slot roll for standalone text: old letters roll away as
 * new ones land, left to right. The same motion as StatefulButton's labels.
 */
export function TextCascade({
  text,
  className = "",
  disableAnimation = false,
  accessibilityLabel,
  ...props
}: TextCascadeProps) {
  const reducedMotion = useReducedMotionPreference();

  return (
    <View
      {...props}
      accessible
      accessibilityRole="text"
      accessibilityLabel={accessibilityLabel ?? text}
      style={[{ alignSelf: "flex-start" }, props.style]}
    >
      <CascadeText
        textKey={text}
        text={text}
        className={className}
        reduce={reducedMotion || disableAnimation}
      />
    </View>
  );
}

import { useEffect } from "react";
import { StyleSheet, Text, View, type ViewProps } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { EASE_OUT } from "../../styles/motion";

const DEFAULT_SPRING = { stiffness: 140, damping: 26, mass: 1.2 };

type Offset = number | `${number}%`;

export type TextRevealProps = Omit<ViewProps, "children"> & {
  /** One string, or several lines. */
  text: string | string[];
  /** Animates whole words (the default) or single characters. */
  split?: "word" | "char";
  /** Delay between units in milliseconds. Defaults to 90. */
  stagger?: number;
  /** Delay before the first unit in milliseconds. */
  delay?: number;
  /** Rise distance: points, or a percentage of the line height. Defaults to "40%". */
  yOffset?: Offset;
  spring?: { stiffness?: number; damping?: number; mass?: number };
  /** Text style for every unit, such as `text-3xl font-semibold`. */
  className?: string;
  /** Disables the rise independently of the system preference. */
  disableAnimation?: boolean;
};

type WordGroup = { text: string; trailing: string };

/** Splits a line into words, each carrying the whitespace that follows it. */
function toWordGroups(line: string): WordGroup[] {
  const chunks = line.match(/\S+\s*|\s+/g) ?? [];
  return chunks.map((chunk) => {
    const text = chunk.replace(/\s+$/, "");
    return { text, trailing: chunk.slice(text.length) };
  });
}

// Whitespace-only Text can measure zero-width on Android.
const keepSpaces = (value: string) => value.replace(/ /g, " ");

function Unit({
  text,
  delay,
  offset,
  spring,
  reduce,
  className,
}: {
  text: string;
  delay: number;
  offset: Offset;
  spring: typeof DEFAULT_SPRING;
  reduce: boolean;
  className: string;
}) {
  const rise = useSharedValue(0);
  const fade = useSharedValue(0);
  const height = useSharedValue(0);

  useEffect(() => {
    if (reduce) {
      fade.value = withDelay(
        delay * 0.3,
        withTiming(1, { duration: 250, easing: EASE_OUT }),
      );
      rise.value = 1;
      return;
    }
    const { stiffness, damping, mass } = spring;
    rise.value = withDelay(delay, withSpring(1, { stiffness, damping, mass }));
    fade.value = withDelay(
      delay,
      withTiming(1, { duration: 700, easing: EASE_OUT }),
    );
    // Depend on the spring's numbers, not its object identity.
  }, [
    delay,
    fade,
    reduce,
    rise,
    spring.stiffness,
    spring.damping,
    spring.mass,
  ]);

  const percent = typeof offset === "string" ? Number.parseFloat(offset) : null;

  const animatedStyle = useAnimatedStyle(() => {
    const distance =
      percent === null ? (offset as number) : (height.value * percent) / 100;
    return {
      opacity: fade.value,
      transform: [{ translateY: (1 - rise.value) * distance }],
    };
  });

  return (
    <Animated.View
      style={animatedStyle}
      onLayout={({ nativeEvent: { layout } }) => {
        height.value = layout.height;
      }}
    >
      <Text className={className}>{keepSpaces(text)}</Text>
    </Animated.View>
  );
}

/** Words or characters that rise into place on a spring, one after another. */
export function TextReveal({
  text,
  split = "word",
  stagger = 90,
  delay = 0,
  yOffset = "40%",
  spring,
  className = "",
  disableAnimation = false,
  accessibilityLabel,
  ...props
}: TextRevealProps) {
  const reducedMotion = useReducedMotionPreference();
  const reduce = reducedMotion || disableAnimation;
  const lines = Array.isArray(text) ? text : [text];
  const physics = { ...DEFAULT_SPRING, ...spring };
  let unitIndex = 0;

  const renderUnit = (unit: string, key: string) => {
    const unitDelay = delay + unitIndex * stagger;
    unitIndex += 1;
    return (
      <Unit
        key={key}
        text={unit}
        delay={unitDelay}
        offset={yOffset}
        spring={physics}
        reduce={reduce}
        className={className}
      />
    );
  };

  return (
    <View
      {...props}
      accessible
      accessibilityLabel={accessibilityLabel ?? lines.join("\n")}
    >
      {lines.map((line, lineIndex) => (
        // Lines and units are positional; the whole tree remounts with new text.
        <View key={`${lineIndex}-${line}`} style={styles.line}>
          {toWordGroups(line).map((group, groupIndex) => {
            const whole = group.text + group.trailing;
            const key = `${groupIndex}-${whole}`;
            if (split !== "char") return renderUnit(whole, key);
            // Each word stays together so lines wrap between words, not inside them.
            return (
              <View key={key} style={styles.word}>
                {Array.from(whole).map((char, charIndex) =>
                  renderUnit(char, `${charIndex}-${char}`),
                )}
              </View>
            );
          })}
        </View>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  line: { flexDirection: "row", flexWrap: "wrap" },
  word: { flexDirection: "row" },
});

import { useEffect, useRef, useState } from "react";
import { Text, type TextProps } from "react-native";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";

const DEFAULT_GLYPHS = "ABCDEFGHJKLMNPQRSTUVWXYZ0123456789#%&@$?/";
// Scrambled glyphs change at most this often, in milliseconds.
const FRAME = 40;

export type TextScrambleProps = Omit<TextProps, "children"> & {
  /** Final text. Changing it scrambles toward the new value. */
  text: string;
  /** Total duration in milliseconds. Defaults to 32 ms per character, within 420–760. */
  duration?: number;
  /** Characters sampled while positions are unresolved. */
  glyphs?: string;
  /** Disables scrambling independently of the system preference. */
  disableAnimation?: boolean;
  className?: string;
};

/** Characters scramble through random glyphs and settle left to right on `text`. */
export function TextScramble({
  text,
  duration,
  glyphs = DEFAULT_GLYPHS,
  disableAnimation = false,
  className = "",
  accessibilityLabel,
  ...props
}: TextScrambleProps) {
  const reducedMotion = useReducedMotionPreference();
  const animate = !reducedMotion && !disableAnimation;
  const [display, setDisplay] = useState(text);
  const mounted = useRef(false);

  useEffect(() => {
    // The first text appears as is; later changes scramble.
    if (!mounted.current) {
      mounted.current = true;
      setDisplay(text);
      return;
    }
    if (!animate || !glyphs) {
      setDisplay(text);
      return;
    }

    const characters = Array.from(text);
    const total =
      duration ?? Math.min(760, Math.max(420, characters.length * 32));
    const startedAt = Date.now();
    let lastUpdate = 0;
    let frame = 0;

    const tick = () => {
      const now = Date.now();
      if (now - lastUpdate >= FRAME) {
        lastUpdate = now;
        const settled = Math.floor(
          Math.min((now - startedAt) / total, 1) * characters.length,
        );
        setDisplay(
          characters
            .map((character, index) =>
              index < settled || character === " "
                ? character
                : glyphs[Math.floor(Math.random() * glyphs.length)],
            )
            .join(""),
        );
      }
      if (now - startedAt < total) frame = requestAnimationFrame(tick);
      else setDisplay(text);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [animate, duration, glyphs, text]);

  return (
    <Text
      {...props}
      // Screen readers get the final text, never the scrambled frames.
      accessibilityLabel={accessibilityLabel ?? text}
      className={className}
    >
      {animate ? display : text}
    </Text>
  );
}

import { useEffect } from "react";
import { View, type ViewProps } from "react-native";
import Animated, {
  cancelAnimation,
  Easing,
  interpolateColor,
  ReduceMotion,
  useSharedValue,
  withRepeat,
  withTiming,
} from "react-native-reanimated";
import { useResolveClassNames } from "uniwind";
import { useReducedMotionPreference } from "../../hooks/use-reduced-motion";
import { GlyphRow } from "../../primitives/glyph-row";

// The web gradient is twice the text's width with its highlight 40% either side
// of its middle, swept from 200% to -200% background position. In text widths
// that is a highlight 0.4 wide whose center travels from -1 to 3.
const BAND = 0.4;
const SWEEP_FROM = -1;
const SWEEP_TO = 3;

export type TextShimmerProps = Omit<ViewProps, "children"> & {
  children: string;
  /** One sweep in milliseconds. Defaults to 2500. */
  duration?: number;
  /** Text style, such as `text-xl font-semibold`. Colors come from the theme. */
  className?: string;
  /** Disables the sweep independently of the system preference. */
  disableAnimation?: boolean;
};

/** A highlight that sweeps across muted text, for loading and thinking states. */
export function TextShimmer({
  children,
  duration = 2500,
  className = "",
  disableAnimation = false,
  accessibilityLabel,
  ...props
}: TextShimmerProps) {
  const reducedMotion = useReducedMotionPreference();
  const animate = !reducedMotion && !disableAnimation;
  const { color: base } = useResolveClassNames("text-muted");
  const { color: highlight } = useResolveClassNames("text-foreground");
  const progress = useSharedValue(0);
  const baseColor = String(base ?? "gray");
  const highlightColor = String(highlight ?? "black");

  useEffect(() => {
    if (!animate) {
      cancelAnimation(progress);
      progress.value = 0;
      return;
    }
    progress.value = 0;
    progress.value = withRepeat(
      withTiming(1, {
        duration,
        easing: Easing.linear,
        reduceMotion: ReduceMotion.Never,
      }),
      -1,
    );
    return () => cancelAnimation(progress);
  }, [animate, duration, progress]);

  const colorAt = (p: number, position: number) => {
    "worklet";
    const center = SWEEP_FROM + (SWEEP_TO - SWEEP_FROM) * p;
    const lit = Math.max(0, 1 - Math.abs(position - center) / BAND);
    return {
      color: interpolateColor(lit, [0, 1], [baseColor, highlightColor]),
      opacity: 1,
    };
  };

  return (
    <View
      {...props}
      accessible
      accessibilityRole="text"
      accessibilityLabel={accessibilityLabel ?? children}
      style={[{ alignSelf: "flex-start" }, props.style]}
    >
      {animate ? (
        <GlyphRow
          text={children}
          className={className}
          progress={progress}
          colorAt={colorAt}
        />
      ) : (
        <Animated.Text className={className} style={{ color: baseColor }}>
          {children}
        </Animated.Text>
      )}
    </View>
  );
}

